// Ported from nuxt/ui v3.0.2 `src/theme/alert.ts` and adapted for Vue-Lynx:
// dark rides the semantic tokens, `dark:` / `focus-visible:` / `shadow-*` are
// dropped, and variants are restricted to `solid` / `outline` / `soft` /
// `subtle`. Semantic colors resolve via the app's CSS vars (see `button.ts`).
import type { Color } from '@@vyui:theme/colors'
import { type IconFg, iconFgFromToken } from '@@vyui:theme/iconColor'

// Variant = structural treatment only (border / fill / nothing); the hue stays
// the same across variants. Use `border-*`, not `ring-*` — Lynx-native drops the
// ring's multi-var chain — and mimic translucent rings/fills with discrete
// shades, since the preset can't do opacity modifiers (`ring/25`→`-200`,
// `bg/10`→`-50`). See `theme/button.ts` for the full rationale.
//
// Surface (`base`) is kept separate from the foreground color (`fg`): CSS
// inheritance is OFF in the Lynx build, so `text-*` on `root` never reaches the
// title / description / icon — `variantClass` spreads `fg` onto those slots.
const solid = (c: string) =>
  ({ base: `bg-${c}-500`, fg: 'text-white' })

const outline = (c: string) =>
  ({ base: `bg-default border-2 border-solid border-${c}-200`, fg: `text-${c}-600` })

const subtle = (c: string) =>
  ({ base: `bg-${c}-50 border-2 border-solid border-${c}-200`, fg: `text-${c}-600` })

const soft = (c: string) =>
  ({ base: `bg-${c}-50`, fg: `text-${c}-600` })

const ghost = (c: string) =>
  ({ base: '', fg: `text-${c}-600` })

const VARIANT_BUILDERS = { solid, outline, subtle, soft, ghost } as const

export type Variant = keyof typeof VARIANT_BUILDERS

const VARIANTS = Object.keys(VARIANT_BUILDERS) as Variant[]

const variantClass = (color: string, variant: Variant) => {
  const { base, fg } = VARIANT_BUILDERS[variant](color)
  return { root: base, title: fg, description: fg, icon: fg }
}

// Same Lynx constraint as `button.ts`'s `iconFg`: the `<svg>` rasterizes its
// XML, so the `text-*` class on the `icon` slot never reaches the glyph — the
// fill is baked in via the Icon `color` prop, derived from the same `fg` string
// the variant emits so class and baked color can't drift.
export function iconFg(color: string, variant: Variant, isDark = false): IconFg {
  const { fg } = VARIANT_BUILDERS[variant](color)
  return iconFgFromToken(fg.match(/^text-(\S+)/)?.[1], isDark)
}

export default (colors: Color[]) => ({
  slots: {
    root: 'relative w-full rounded-lg p-4 flex flex-row gap-2.5',
    wrapper: 'min-w-0 flex-1 flex flex-col',
    title: 'text-sm font-medium',
    description: 'text-sm opacity-90',
    icon: 'shrink-0 size-5',
    actions: 'flex flex-row flex-wrap gap-1.5 shrink-0',
    close: 'p-0',
  },
  variants: {
    color: Object.fromEntries(colors.map(c => [c, ''])) as Record<Color, ''>,
    variant: Object.fromEntries(VARIANTS.map(v => [v, ''])) as Record<Variant, ''>,
    orientation: {
      horizontal: {
        root: 'items-center',
        actions: 'items-center',
      },
      vertical: {
        root: 'items-start',
        actions: 'items-start mt-2.5',
      },
    },
    title: {
      true: {
        description: 'mt-1',
      },
    },
  },
  compoundVariants: [
    ...colors.flatMap(color =>
      VARIANTS.map(variant => ({
        color,
        variant,
        class: variantClass(color, variant),
      })),
    ),
  ],
  defaultVariants: {
    color: 'primary' as const,
    variant: 'solid' as const,
    orientation: 'vertical' as const,
  },
})

// Bake-time icon-color resolution, shared by the component themes.
//
// Lynx rasterizes each `<svg>`, so a `text-*` class on an icon slot never
// reaches the glyph — the fill is baked into the SVG via the Icon `color` prop
// (`resolveColorHex`). This maps the foreground CLASS a theme emits to a
// `{ semantic, shade }` descriptor for that resolver.
//
// Accent classes (`text-primary-600`) are mode-independent — the accent ramps
// don't invert. Semantic TOKENS (`text-muted`, …) resolve to different neutral
// shades in light vs dark, so callers pass the live `isDark` and the baked fill
// tracks the mode the way the CSS token would.

export type IconFg = { semantic: string, shade: number } | 'white'

const N = (shade: number): IconFg => ({ semantic: 'neutral', shade })

// suffix (the part after `text-`) → per-mode neutral fill. Mirrors the
// `--ui-text-*` values in `style.css` (light `:root`, dark `.dark`).
const SEMANTIC_TOKEN: Record<string, { light: IconFg, dark: IconFg }> = {
  highlighted: { light: N(900), dark: 'white' },
  default: { light: N(700), dark: N(200) },
  toned: { light: N(600), dark: N(300) },
  muted: { light: N(500), dark: N(400) },
  dimmed: { light: N(400), dark: N(500) },
  inverted: { light: 'white', dark: N(900) },
}

/**
 * Resolve an icon fill from a foreground class SUFFIX (the token after `text-`),
 * mode-aware. Returns `'white'` for `text-white`, unknown suffixes, and the
 * token ends that are white in `isDark`.
 */
export function iconFgFromToken(suffix: string | undefined, isDark: boolean): IconFg {
  if (!suffix || suffix === 'white')
    return 'white'
  // accent ramp: `{color}-{shade}` (ramp not inverted → mode-independent)
  const accent = suffix.match(/^([a-z]+)-(\d+)$/)
  if (accent)
    return { semantic: accent[1], shade: Number(accent[2]) }
  const token = SEMANTIC_TOKEN[suffix]
  return token ? token[isDark ? 'dark' : 'light'] : 'white'
}
